/* Test reports generated by the real PowerShell function, in a browser and the
   actual application HTML. All data is synthetic; no server inventory runs. */
const fs=require('fs'),path=require('path'),http=require('http'),assert=require('assert');
const {pathToFileURL}=require('url');
const {chromium}=require('playwright');
const directory=path.resolve('build/report-validation');
const current=fs.readFileSync(path.join(directory,'sample-report.html'));
const original=fs.readFileSync(path.join(directory,'baseline-report.html'));
const empty=fs.readFileSync(path.join(directory,'empty-report.html'));
const main=fs.readFileSync('src/app/main.go','utf8');
const version=main.match(/appVersion\s*=\s*"([^"]+)"/)[1];
const reportPolicy=main.match(/func \(a \*application\) handleCurrentReport[\s\S]*?Set\("Content-Security-Policy", "([^"]+)"\)/)[1];
const appPolicy=main.match(/applicationPageCSP\s*=\s*"([^"]+)"/)[1];
const appHTML=fs.readFileSync('src/app/index.html','utf8').replaceAll('__TOKEN__','report-fixture').replaceAll('__APP_VERSION__',version).replaceAll('__COLLECTOR_VERSION__',version);
const report={status:'running',checks:[],data:'Synthetic only',limitations:['Browser rendering and actual report functions, without live server collection.']};
let flavor='new',server,browser;const errors=[];let externalRequests=0;
function state(){return {appVersion:version,collectorVersion:version,computerName:'DEMO-FS-01',isAdministrator:true,powerShellVersion:'5.1',logs:[],nextLogIndex:0,status:'idle',running:false,loadedReportAvailable:true,loadedReportPath:'Synthetic report',loadedReportName:'DEMO-FS-01',loadedReportPackage:'Synthetic package',loadedReportDocxPath:'Synthetic Word report',loadedReportSummaryPath:'Synthetic summary',loadedReportSerial:flavor==='new'?1:2,update:{status:'current',title:'Up to date',installedVersion:version,latestVersion:version,canCheck:true,notes:[]}};}
async function check(name,action){await action();report.checks.push({name,result:'passed'});console.log('PASS: '+name);}
async function models(page){return page.evaluate(()=>Array.from(document.querySelectorAll('.report-section table')).map(table=>{
 const panel=table.closest('details'),heading=table.parentElement.previousElementSibling;
 return {title:panel?panel.getAttribute('data-title'):heading.textContent.trim(),columns:Array.from(table.querySelectorAll('thead th')).map(c=>c.getAttribute('data-original-label')||c.textContent),rows:Array.from(table.querySelectorAll('tbody tr')).map(row=>Array.from(row.cells).map(c=>c.textContent))};
}).sort((a,b)=>a.title.localeCompare(b.title)));}
async function newContext(options={}){
 const context=await browser.newContext(options);
 await context.route('**/*',route=>{
  const url=route.request().url();if(!url.startsWith('http://127.0.0.1:')&&!url.startsWith('file:')&&!url.startsWith('data:')){externalRequests++;return route.abort()}
  return route.continue();
 });
 context.on('page',page=>page.on('pageerror',e=>errors.push(e.message)));
 return context;
}
(async()=>{
 server=http.createServer((req,res)=>{
  const route=req.url.split('?')[0];
  if(route==='/app'){res.setHeader('Content-Type','text/html');res.setHeader('Content-Security-Policy',appPolicy);return res.end(appHTML)}
  if(['/new','/old','/empty','/report/current'].includes(route)){
   res.setHeader('Content-Type','text/html; charset=utf-8');res.setHeader('Content-Security-Policy',reportPolicy);
   return res.end(route==='/old'?original:route==='/empty'?empty:route==='/report/current'&&flavor==='old'?original:current);
  }
  if(route==='/app-icon.svg'||route==='/app-icon.png'||route==='/favicon.ico'){
   res.setHeader('Content-Type',route.endsWith('svg')?'image/svg+xml':route.endsWith('png')?'image/png':'image/x-icon');return res.end(fs.readFileSync(route.endsWith('svg')?'src/app/assets/icons/server-inventory.svg':'src/app/'+route.slice(1)));
  }
  res.setHeader('Content-Type','application/json');res.end(JSON.stringify(route==='/api/state'?state():{}));
 });
 await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));const base='http://127.0.0.1:'+server.address().port;
 const arg=process.argv.indexOf('--executable');browser=await chromium.launch(arg>=0?{headless:true,executablePath:process.argv[arg+1],args:process.platform==='linux'?['--no-sandbox']:[]}:{channel:'msedge',headless:true});
 const context=await newContext({viewport:{width:1440,height:1000}});const page=await context.newPage();
 await page.goto(base+'/old');const oldModels=await models(page),oldPre=await page.locator('pre').allTextContents();
 const oldNav=await page.locator('.subsection-nav-button:visible').count();
 await page.locator('.section-main-button').filter({hasText:'Executive Summary'}).click();
 const oldVisibleTables=await page.locator('.report-section.active table:visible').count();
 await page.screenshot({path:path.join(directory,'report-before.png')});
 await page.goto(base+'/new');
 await check('All original table columns, cells, rows and multiline outputs remain available',async()=>{
  assert.deepStrictEqual(await models(page),oldModels);assert.deepStrictEqual(await page.locator('pre').allTextContents(),oldPre);
  report.tables=oldModels.length;report.rows=oldModels.reduce((n,t)=>n+t.rows.length,0);
 });
 await check('Summary opens first with fewer visible tables and navigation links than the original report',async()=>{
  assert.equal(await page.locator('.report-section.active h2').textContent(),'Executive Summary');
  const newNav=await page.locator('.subsection-nav-button:visible').count(),tables=await page.locator('.report-section.active table:visible').count();
  assert(newNav<oldNav&&tables<oldVisibleTables);assert.equal(await page.locator('.nav-group.active').count(),1);
  report.negativeControl={oldVisibleSubsectionLinks:oldNav,newVisibleSubsectionLinks:newNav,oldSummaryTables:oldVisibleTables,newSummaryTables:tables};
 });
 await check('Collection failures and recovery gaps stay expanded ahead of routine datasets',async()=>{
  assert.equal(await page.locator('.report-section.active .dataset-priority[open]').count(),2);
  assert.equal(await page.locator('.metric-review .metric-value').textContent(),'2');
  const position=await page.locator('.report-section.active').evaluate(section=>{const p=section.querySelector('.dataset-priority'),r=section.querySelector('[data-title="Server identity and baseline"]');return p.getBoundingClientRect().top<r.getBoundingClientRect().top});assert(position);
 });
 await check('Readable column labels preserve ordinary words and separate camel-case field names',async()=>{
  const labels=await page.locator('[data-title="Collection failures requiring review"] th').allTextContents();
  assert.deepStrictEqual(labels,['Collector','Status','Error Message']);
  assert.equal(await page.locator('[data-title="Collector execution status"] th').last().textContent(),'Duration Sec');
 });
 await page.screenshot({path:path.join(directory,'report-summary.png')});
 await check('Section expand/collapse controls expose all retained rows on request',async()=>{
  await page.locator('.section-main-button[data-title="Network Configuration"]').click();
  const section=page.locator('.report-section.active');await section.locator('[data-details-action="expand"]').click();
  assert.equal(await section.locator('details[open]').count(),await section.locator('details').count());
  assert.equal(await section.locator('[data-title="Routing table"] tbody tr').count(),1500);
  await section.locator('[data-details-action="collapse"]').click();assert.equal(await section.locator('details[open]').count(),0);
 });
 await page.screenshot({path:path.join(directory,'report-network.png')});
 await check('Full-report search reveals the last row inside an inactive collapsed dataset',async()=>{
  await page.locator('.section-main-button[data-title="Executive Summary"]').click();
  await page.locator('#report-search-input').fill('FINALROW-1500');await page.locator('#report-search-input').press('Enter');
  await page.locator('mark.report-current').waitFor({state:'visible'});
  assert.equal(await page.locator('.report-section.active h2').textContent(),'Network Configuration');
  assert.equal(await page.locator('[data-title="Routing table"][open]').count(),1);
  assert((await page.locator('#report-search-message').textContent()).includes('1 of 1'));
 });
 await check('Search also reveals raw output and supports next, previous, clear and no-match states',async()=>{
  const input=page.locator('#report-search-input');await input.fill('LAST-RAW-LINE');await input.press('Enter');assert(await page.locator('mark.report-current').isVisible());
  await input.fill('Departments');await input.press('Enter');const first=await page.locator('#report-search-message').textContent();await page.locator('#report-search-next').click();assert.notEqual(await page.locator('#report-search-message').textContent(),first);await page.locator('#report-search-prev').click();assert.equal(await page.locator('#report-search-message').textContent(),first);
  await input.fill('no-such-synthetic-value');await input.press('Enter');assert((await page.locator('#report-search-message').textContent()).startsWith('No matches'));
  await page.locator('#report-search-clear').click();assert.equal(await page.locator('mark.report-match').count(),0);
 });
 await check('Inventory HTML-like values and search queries remain escaped text with no external requests',async()=>{
  await page.locator('#report-search-input').fill('<script>');await page.locator('#report-search-input').press('Enter');assert(await page.locator('mark.report-current').isVisible());
  assert.equal(await page.evaluate(()=>window.__reportInjected),undefined);assert.equal(externalRequests,0);
  assert.equal(await page.locator('.report-section script,.report-section img').count(),0);
  await page.locator('#report-search-clear').click();
 });
 await check('Existing row-limit notices and empty dataset explanations remain visible when opened',async()=>{
  await page.locator('.section-main-button[data-title="Network Configuration"]').click();
  const panel=page.locator('[data-title="Truncated source snapshot"]');await panel.locator('summary').click();assert((await panel.textContent()).includes('2 of 3 rows'));assert((await panel.textContent()).includes('complete dataset remains'));
  await page.locator('.section-main-button[data-title="Role-Specific Configuration"]').click();await page.locator('[data-title="DFS namespaces"] summary').click();assert(await page.locator('[data-title="DFS namespaces"] .empty-data').isVisible());
 });
 await check('Dataset deep links and keyboard activation open the intended section and details',async()=>{
  const id=await page.locator('[data-title="Routing table"]').getAttribute('id');await page.goto(base+'/new#'+id);assert.equal(await page.locator('[data-title="Routing table"][open]').count(),1);
  await page.locator('[data-title="Routing table"] summary').focus();await page.keyboard.press('Enter');assert.equal(await page.locator('[data-title="Routing table"][open]').count(),0);
 });
 await check('Print includes every section and dataset and restores screen expansion state',async()=>{
  const before=await page.locator('details.dataset').evaluateAll(list=>list.map(x=>x.open));
  await page.evaluate(()=>window.SICMReport.preparePrint());await page.emulateMedia({media:'print'});
  assert.equal(await page.locator('.report-section:visible').count(),await page.locator('.report-section').count());assert.equal(await page.locator('details[open]').count(),await page.locator('details').count());
  assert.equal(await page.locator('.dataset-long .table-wrap').first().evaluate(e=>getComputedStyle(e).maxHeight),'none');
  await page.pdf({path:path.join(directory,'report-print.pdf'),format:'A4',landscape:true,printBackground:true,preferCSSPageSize:true});
  await page.evaluate(()=>window.SICMReport.restorePrint());await page.emulateMedia({media:'screen'});
  assert.deepStrictEqual(await page.locator('details.dataset').evaluateAll(list=>list.map(x=>x.open)),before);
 });
 await check('Narrow screens use a collapsible section menu without page-level horizontal overflow',async()=>{
  await page.setViewportSize({width:390,height:844});await page.goto(base+'/new');assert(await page.locator('#toggle-report-nav').isVisible());
  assert(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth+1));
  await page.locator('#toggle-report-nav').click();assert(await page.locator('.report-nav').isVisible());
  await page.locator('.section-main-button[data-title="Network Configuration"]').click();assert(!(await page.locator('.report-nav').isVisible()));
  await page.screenshot({path:path.join(directory,'report-mobile.png')});
 });
 await check('Missing metadata is labelled Not collected instead of zero or healthy',async()=>{
  await page.goto(base+'/empty');assert.equal(await page.locator('.metric-value').filter({hasText:'Not collected'}).count(),4);assert.equal(await page.locator('.metric-review').count(),0);
 });
 await context.close();
 await check('Standalone saved HTML works offline without a server or external assets',async()=>{
  const offline=await newContext({offline:true,viewport:{width:1440,height:1000}});try{const p=await offline.newPage();await p.goto(pathToFileURL(path.join(directory,'sample-report.html')).href);await p.locator('#report-search-input').fill('FINALROW-1500');await p.locator('#report-search-input').press('Enter');assert(await p.locator('mark.report-current').isVisible())}finally{await offline.close()}
 });
 await check('No-script fallback retains every section and starts with all datasets open',async()=>{
  const noScript=await newContext({javaScriptEnabled:false});try{const p=await noScript.newPage();await p.goto(base+'/new');assert.equal(await p.locator('details[open]').count(),await p.locator('details').count());assert.equal(await p.locator('.report-section:visible').count(),await p.locator('.report-section').count());assert.deepStrictEqual(await models(p),oldModels)}finally{await noScript.close()}
 });
 const embedded=await newContext({viewport:{width:1440,height:1100}});const app=await embedded.newPage();
 await check('Application viewer respects the new report layout and reveals collapsed search hits',async()=>{
  flavor='new';await app.goto(base+'/app');await app.locator('#tabButtonReport').click();const frame=app.frameLocator('#reportFrame');
  await frame.locator('html.embedded-report').waitFor();assert.equal(await frame.locator('#appViewerScrollLayout').count(),0);assert(!(await frame.locator('.standalone-tools').isVisible()));
  await app.locator('#viewerSearchInput').fill('FINALROW-1500');await app.locator('#viewerSearchButton').click();await frame.locator('mark.app-viewer-current').waitFor({state:'visible'});
  assert.equal(await frame.locator('[data-title="Routing table"][open]').count(),1);await app.screenshot({path:path.join(directory,'report-embedded.png')});
 });
 await check('Previously generated reports still navigate and search in the unchanged legacy viewer',async()=>{
  flavor='old';await app.goto(base+'/app');await app.locator('#tabButtonReport').click();const frame=app.frameLocator('#reportFrame');await frame.locator('#appViewerScrollLayout').waitFor({state:'attached'});
  await app.locator('#viewerSearchInput').fill('FINALROW-1500');await app.locator('#viewerSearchButton').click();await frame.locator('mark.app-viewer-current').waitFor({state:'visible'});
 });
 await embedded.close();
 await check('Report and viewer execution produces no script errors or external requests',async()=>{assert.deepStrictEqual(errors,[]);assert.equal(externalRequests,0)});
 report.status='passed';
})().catch(error=>{report.status='failed';report.error=error.stack;console.error(error);process.exitCode=1}).finally(async()=>{
 if(browser)await browser.close();if(server)await new Promise(resolve=>server.close(resolve));
 fs.writeFileSync(path.join(directory,'browser-results.json'),JSON.stringify(report,null,2));
});
